                    "sql": "CREATE TABLE IF NOT EXISTS thd-pharma-wh.MAPLEMONK.thd_pharma_wh_ga_sessions_consolidated ( date DATE, shop_name STRING, Channel STRING, sessions INT64, Brand STRING ); Create or replace table thd-pharma-wh.MAPLEMONK.thd_pharma_wh_Sales_Cost_Source as with Sessions as ( select date date, channel marketing_channel, case when lower(brand) like \'%ozone%\' then \'SHOPIFY - OZONE SIGNATURE\' else UPPER(SHOP_NAME) end marketplace, Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DB\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as Brand, sum(sessions) Sessions from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_ga_sessions_consolidated group by 1,2,3,4 ), returnsales as ( select cast(return_date as date) return_date ,marketing_channel ,case when lower(marketplace) like any (\'%amazon%\') then \'AMAZON\' when lower(marketplace) like any (\'%shopify%\') and lower(brand) like \'%dream%\' then \'SHOPIFY - DB\' when lower(marketplace) like any (\'%shopify%\') and lower(brand) like \'%ozone%\' then \'SHOPIFY - OZONEAYURVEDICS\' else upper(marketplace) end as marketplace ,Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DB\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as brand ,sum(total_return_amount) TOTAL_RETURN_AMOUNT ,sum(total_return_amount_excl_tax) TOTAL_RETURN_AMOUNT_EXCL_TAX ,sum(total_returned_quantity) TOTAL_RETURNED_QUANTITY from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_RETURNS_CONSOLIDATED group by 1,2,3,4 order by 1 desc ), orders as ( select cast(FI.order_date as date) Date ,upper(marketplace) Marketplace ,upper(FI.CHANNEL) marketing_CHANNEL ,Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DB\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as Brand ,upper(FI.product_sub_category) as Sub_Category ,Case when upper(marketplace) like \'%B2B%\' then \'B2B\' when upper(marketplace) like \'%SHOPIFY%\' then \'D2C\' else \'B2C\' end as Channel_type ,count(distinct FI.commonsku) as Number_Of_SKU ,sum(ifnull(FI.COGS_Value,0)) as Sum_Of_COGS ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) Total_Sales ,ifnull(sum(ifnull(FI.SELLING_PRICE,0)),0) - ifnull(sum(case when (lower(ifnull(ORDER_STATUS,\'\')) like \'%cancel%\' or lower(ifnull(FINAL_SHIPPING_STATUS,\'\')) like \'%cancel%\') then ifnull(FI.SELLING_PRICE,0) else 0 end),0) TOTAL_SALES_EXCL_CANCL , ifnull(sum(Case when Lower(order_status) like \'%pending%\' then ifnull(FI.Selling_price,0) else 0 end),0) as Pending_Sales ,count(distinct FI.order_id) Total_Orders ,count(distinct FI.order_id) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.order_id end) Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) as New_Customer_Orders ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.order_id end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') then FI.order_id end)) as New_Customer_Orders_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) as Total_New_Customers ,count(distinct(case when lower(FI.new_customer_flag) = \'new\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'new\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end)) New_Customers_EXCL_CANCL ,count(distinct FI.customer_id_final) as TOTAL_Unique_Customers ,(count(distinct FI.customer_id_final) - count(distinct case when lower(FI.order_status) in (\'cancelled\') then FI.customer_id_final end)) as Unique_Customers_EXCL_CANCL ,count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) as Repeat_Customers ,(count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' then FI.customer_id_final end)) - count(distinct(case when lower(FI.new_customer_flag) = \'repeat\' and lower(FI.order_status) in (\'cancelled\') and FI.return_flag = 0 then FI.customer_id_final end))) Repeat_Customers_EXCL_CANCL ,ifnull(sum(FI.discount),0) TOTAL_DISCOUNT ,(ifnull(sum(FI.discount),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.discount end),0)) TOTAL_DISCOUNT_EXCL_CANCL ,ifnull(sum(FI.tax),0) TOTAL_TAX ,(ifnull(sum(FI.tax),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.tax end),0)) TAX_EXCL_CANCL ,ifnull(sum(FI.shipping_price),0) TOTAL_SHIPPING_PRICE ,(ifnull(sum(FI.shipping_price),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.shipping_price end),0)) SHIPPING_PRICE_EXCL_CANCL ,ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' then FI.discount end),0) as New_Customer_Discount ,(ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' then FI.discount end),0) - ifnull(sum(case when lower(FI.new_customer_flag) = \'new\' and lower(order_status) in (\'cancelled\') then FI.discount end),0)) as New_Customer_Discount_EXCL_CANCL ,ifnull(sum(FI.quantity),0) TOTAL_QUANTITY ,(ifnull(sum(FI.quantity),0) - ifnull(sum(case when lower(FI.order_status) in (\'cancelled\') then FI.quantity end),0)) QUANTITY_EXCL_CANCL ,ifnull(sum(case when FI.return_flag=1 then FI.quantity end),0) as Return_Quantity ,ifnull(sum(case when FI.return_flag=1 then ifnull(FI.SELLING_PRICE,0) end),0) as Return_Value ,count(distinct case when lower(order_status) in (\'cancelled\') then order_id end) Cancelled_Orders ,count(distinct case when lower(order_status) not in (\'cancelled\') and return_flag=0 then order_id end) Net_Orders ,count(distinct case when lower(order_status) in (\'delivered\') then order_id end) Delivered_Orders ,count(distinct case when lower(order_status) in (\'returned\',\'rto\') then order_id end) Returned_Orders ,count(distinct case when dispatch_date is not null and lower(order_status) not in (\'cancelled\') then order_id end) Dispatched_Orders ,count(distinct case when lower(order_status) in (\'shipped\',\'printed\',\'confirmed\',\'returned\',\'ready to dispatch\') then order_id end) Realised_Orders ,ifnull(sum(case when lower(order_status) in (\'delivered\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Delivered_Revenue ,ifnull(sum(case when lower(order_status) in (\'returned\',\'rto\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0) Returned_Revenue ,ifnull(sum(case when dispatch_date is not null and lower(order_status) not in (\'cancelled\') then ifnull(FI.SELLING_PRICE,0) end),0) Dispatched_Revenue ,ifnull(sum(case when lower(order_status) in (\'shipped\',\'printed\',\'confirmed\',\'returned\',\'ready to dispatch\') then ifnull(FI.SELLING_PRICE,0) end),0) Realised_Revenue ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -3 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L3M_Customers_Retained ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -6 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L6M_Customers_Retained ,count(case when date_trunc(acquisition_date, month)>=DATE_ADD(DATE_TRUNC(order_date, MONTH), INTERVAL -12 MONTH) and date_trunc(acquisition_date, month)<date_trunc(order_date, month) then customer_id_final end) L12M_Customers_Retained ,sum(case when lower(FI.new_customer_flag) = \'repeat\' then ifnull(FI.selling_price,0) end) Repeat_Customer_Revenue ,count(distinct case when lower(FI.payment_mode) in (\'cod\') then FI.order_id end) as COD_Orders from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SALES_CONSOLIDATED FI group by 1,2,3,4,5,6 ), monthly_qty AS ( SELECT DATE_TRUNC(Date, MONTH) AS month, Marketplace, SUM(TOTAL_QUANTITY) AS monthly_total_quantity FROM orders GROUP BY 1,2 ), monthly_qty_mom AS ( SELECT month, Marketplace, monthly_total_quantity, LAG(monthly_total_quantity) OVER ( PARTITION BY Marketplace ORDER BY month ) AS prev_month_qty FROM monthly_qty ), orders_with_mom AS ( SELECT o.*, m.prev_month_qty FROM orders o LEFT JOIN monthly_qty_mom m ON DATE_TRUNC(o.Date, MONTH) = m.month AND LOWER(o.Marketplace) = LOWER(m.Marketplace) ), spendd2c as (select date ,case when lower(channel) like \'%facebook%\' and lower(brand) like \'%db%\' then \'SHOPIFY - DB\' when lower(channel) like \'%facebook%\' and lower(brand) like \'%ozone%\' then \'SHOPIFY - OZONEAYURVEDICS\' when lower(channel) like any (\'%amazon%\') then \'AMAZON\' when lower(channel) like \'%flipkart%\' then \'FLIPKART\' when lower(channel) like \'%myntra%\' then \'MYNTRA\' else upper(channel) end as Marketplace ,upper(channel) marketing_Channel ,Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DB\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as Brand ,sum(ifnull(spend,0)) as spend ,sum(ifnull(impressions,0)) as ad_impressions ,sum(ifnull(clicks,0)) as ad_clicks ,sum(ifnull(conversions,0)) as ad_conversions ,sum(ifnull(conversion_value,0)) as ad_sales from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_MARKETING_CONSOLIDATED group by 1,2,3,4 ) select coalesce(fi.Date,MC.date, SC.date) as date, upper(coalesce(fi.marketplace,MC.marketplace,RS.marketplace, SC.marketplace)) as Marketplace, upper(coalesce(fi.marketing_channel,MC.marketing_Channel,RS.marketing_channel, SC.marketing_channel)) as Marketing_Channel, upper(coalesce(fi.brand, mc.brand, rs.brand, sc.brand)) as Brand, Total_Sales, TOTAL_SALES_EXCL_CANCL, Pending_Sales, SC.sessions, Total_Orders, Orders_EXCL_CANCL, New_Customer_Orders, New_Customer_Orders_EXCL_CANCL, Total_New_Customers, New_Customers_EXCL_CANCL, TOTAL_Unique_Customers, Unique_Customers_EXCL_CANCL, Repeat_Customers, Repeat_Customers_EXCL_CANCL, TOTAL_DISCOUNT, TOTAL_DISCOUNT_EXCL_CANCL, TOTAL_TAX, TAX_EXCL_CANCL, TOTAL_SHIPPING_PRICE, SHIPPING_PRICE_EXCL_CANCL, New_Customer_DISCOUNT, New_Customer_Discount_EXCL_CANCL, TOTAL_QUANTITY, FI.prev_month_qty, SAFE_DIVIDE( FI.prev_month_qty - TOTAL_QUANTITY, FI.prev_month_qty ) AS MOM_CHANGE_PCT, QUANTITY_EXCL_CANCL, Returned_Orders, RS.TOTAL_RETURNED_QUANTITY as Return_Quantity, RS.TOTAL_RETURN_AMOUNT as Return_Value, FI.Return_Value as Returned_Value, Cancelled_Orders, Net_Orders, Delivered_Orders, Delivered_Revenue, Dispatched_Orders, Dispatched_Revenue, Realised_Orders, Realised_Revenue, spend as marketing_spend, COD_Orders, Repeat_Customer_Revenue, MC.ad_conversions, MC.ad_impressions, MC.ad_clicks, MC.ad_sales, Number_Of_SKU, Sum_Of_COGS, FI.Return_Quantity as New_Returned_Qty, FI.Sub_Category, FI.Channel_Type from orders_with_mom FI full outer join spendd2c MC on FI.Date = MC.date and lower(FI.marketing_channel)=lower(MC.marketing_channel) and lower(FI.Marketplace)=lower(MC.Marketplace) full outer join returnsales RS on RS.return_date = coalesce(FI.date, MC.date) and lower(RS.marketing_Channel) = lower(coalesce(FI.marketing_Channel,MC.marketing_channel)) and lower(RS.marketplace)=lower(coalesce(FI.marketplace,MC.marketplace)) full outer join SESSIONS SC on coalesce(FI.Date,MC.date,RS.return_date)=SC.Date and lower(coalesce(FI.Marketing_Channel,MC.marketing_channel,RS.marketing_Channel))=lower(SC.Marketing_Channel) and lower(coalesce(FI.marketplace,MC.marketplace,RS.marketplace))=lower(SC.Marketplace);",
